"""在 PATH 上把命令名解析成磁盘路径。

Windows 上「命令名」通常不带扩展名，例如 ``where``、``git``、``build``。
Shell 之所以能找到它们，是因为按 :envvar:`PATHEXT` 里声明的扩展名顺序
逐个试探。任何要自己启动外部程序的工具都必须照做，否则只能看见 ``.exe``。

两条与 :func:`SearchPath` 一致的规则尤其重要：

* 扩展名的试探顺序就是 :envvar:`PATHEXT` 里声明的顺序，``.exe`` 并不特殊；
* 名字自身已经带着可执行扩展名（``tool.exe``、``build.CMD``）时直接匹配，
  绝不再叠加成 ``tool.exe.exe``。
"""

import os

from .errors import CommandNotFound

#: 找不到 PATHEXT 时使用的兜底扩展名。
EXECUTABLE_EXTENSIONS = (".exe",)


def search_dirs():
    """返回 PATH 中需要搜索的目录列表。"""
    raw = os.environ.get("PATH", "")
    return [d for d in raw.split(os.pathsep) if d]


def executable_extensions():
    """返回按优先级排列的可执行扩展名。

    优先使用环境变量 :envvar:`PATHEXT`；它缺失（或为空）时才退回内置兜底值。
    返回值统一为「带前导点的小写」形式，顺序与 :envvar:`PATHEXT` 中声明的
    一致，重复项只保留第一次出现的位置。
    """
    raw = os.environ.get("PATHEXT") or ""
    extensions = []
    for chunk in raw.split(os.pathsep):
        item = chunk.strip()
        if not item:
            continue
        if not item.startswith("."):
            item = "." + item
        item = item.lower()
        if item not in extensions:
            extensions.append(item)

    if not extensions:
        return EXECUTABLE_EXTENSIONS
    return tuple(extensions)


def candidate_names(name):
    """列出 ``name`` 在单个目录内需要试探的文件名，按优先级排列。

    * 名字已经带着 :envvar:`PATHEXT` 里的扩展名（``direct.CMD``）时，
      只返回它本身 —— 不再叠加扩展名；
    * 名字带着别的扩展名（``build.py``）时，先原样试一次，再按
      :envvar:`PATHEXT` 顺序补全；
    * 名字没有扩展名（``ninja``）时，完全按 :envvar:`PATHEXT` 顺序补全。
    """
    extensions = executable_extensions()
    suffix = os.path.splitext(name)[1]

    if not suffix:
        return tuple(name + extension for extension in extensions)
    if suffix.lower() in extensions:
        return (name,)
    return (name,) + tuple(name + extension for extension in extensions)


def _on_disk_spelling(path):
    """把 ``path`` 的文件名部分换成磁盘上真实的大小写。

    Windows 的文件系统不区分大小写，``hello.cmd`` 与 ``hello.CMD`` 指的是
    同一个文件；调用方拿到的路径却应该和磁盘上的写法一致，这样打印出来
    的日志、以及和别处拼出来的路径做比较才不会莫名其妙地对不上。
    """
    directory, filename = os.path.split(path)
    if not directory or not filename:
        return path

    fallback = None
    try:
        with os.scandir(directory) as entries:
            for entry in entries:
                if entry.name == filename:
                    return path
                if fallback is None and entry.name.lower() == filename.lower():
                    fallback = entry.name
    except OSError:
        return path

    if fallback is None:
        return path
    return os.path.join(directory, fallback)


def _first_existing(directory, names):
    """在 ``directory`` 中按顺序找出第一个真实存在的文件，返回绝对路径。"""
    for filename in names:
        candidate = os.path.join(directory, filename)
        if os.path.isfile(candidate):
            return _on_disk_spelling(os.path.abspath(candidate))
    return None


def resolve(name):
    """把 ``name`` 解析成磁盘上的绝对路径。

    按 :envvar:`PATH` 的目录顺序搜索，目录内再按 :envvar:`PATHEXT` 声明的
    扩展名顺序试探（见 :func:`candidate_names`）。名字里已经带路径分隔符时
    不搜索 :envvar:`PATH`，只在该路径上补全扩展名。

    找不到时抛 :class:`CommandNotFound`。
    """
    if not name:
        raise CommandNotFound(name)

    name = name if isinstance(name, str) else str(name)
    directory, leaf = os.path.split(name)
    names = candidate_names(leaf)

    if directory:
        # 调用方给了（相对或绝对的）路径，就不再翻 PATH。
        found = _first_existing(os.path.abspath(directory), names)
        if found is not None:
            return found
        raise CommandNotFound(name)

    for path_entry in search_dirs():
        found = _first_existing(path_entry, names)
        if found is not None:
            return found

    raise CommandNotFound(name)

